import math

def calculate_probability(type1_expired: int = 5, type2_expired: int = 3) -> float:
    def combination(n: int, k: int) -> int:
        return math.comb(n, k)

    total_cases = 3 * type2_expired  # Number of Type I cases is twice the number of Type II cases
    type1_cases = 2 * type2_expired

    # Calculate probability for each case type
    prob_type1 = (type1_cases / total_cases) * combination(30, 10) / sum(
        [combination(type1_cases + type1_expired, 10), combination(total_cases - type1_cases + type2_expired, 10)]
    )

    prob_type2 = (type2_cases := type2_expired) / total_cases * combination(24, 10) / sum(
        [combination(type1_cases + type1_expired, 10), combination(total_cases - type1_cases + type2_expired, 10)]
    )

    # Calculate the probability that the chosen case is of Type I given 2 expired cans
    return round(prob_type1 / (prob_type1 + prob_type2), 2)

# Test cases
assert calculate_probability() == 0.71
assert calculate_probability(type1_expired=6, type2_expired=2) == 0.8

