from typing import List

def solve_tsp(distances: List[List[int]]) -> int:
    def tsp(current_city: int, visited_cities: set, cities_to_visit: set, cost_so_far: int, memo: dict) -> int:
        if not cities_to_visit and current_city in visited_cities:
            return cost_so_far
        if (current_city, frozenset(visited_cities)) in memo:
            return memo[(current_city, frozenset(visited_cities))]

        min_cost = float('inf')
        for next_city in cities_to_visit:
            if next_city not in visited_cities:
                new_visited = visited_cities | {next_city}
                new_cost = cost_so_far + distances[current_city][next_city]
                remaining_cities = cities_to_visit - {next_city}
                min_cost = min(min_cost, tsp(next_city, new_visited, remaining_cities, new_cost, memo))

        memo[(current_city, frozenset(visited_cities))] = min_cost
        return min_cost

    n = len(distances)
