def solve_tsp(distances: List[List[int]]) -> int:
    def tsp(current_city: int, visited_cities: set, cost_so_far: int, cities_count: int) -> int:
        if len(visited_cities) == cities_count - 1:
            return cost_so_far + distances[current_city][0]

        min_cost = float('inf')
        for next_city in range(cities_count):
            if next_city not in visited_cities:
                new_visited = visited_cities | {next_city}
                new_cost = tsp(next_city, new_visited, cost_so_far + distances[current_city][next_city], cities_count)
                min_cost = min(min_cost, new_cost)

        return min_cost

