    if n < 3 or max_sum < 6:
        return 0

    count = 0
    for i in range(1, n - 1):
        for j in range(i + 1, n):
            k = 2 * j - i
            if k > n:
                break
            if is_arithmetic_progression(i, j, k) and (i + j + k) <= max_sum:
                count += 1

    return count

