def is_valid(grid: List[List[int]]) -> bool:
    return len(set([sum(row) for row in grid])) == 1

def backtrack(nums: List[int], grid: List[List[int]], used: List[bool]) -> int:
    if len(grid[-1]) == 0:
        return 1
    count = 0
    for i, num in enumerate(nums):
        if not used[i]:
            used[i] = True
            grid[len(grid) - 1 - len(grid[-1])].append(num)
            if is_valid(grid):
                count += backtrack(nums, grid, used)
            used[i] = False
            grid[len(grid) - 1 - len(grid[-1])].pop()
    return count

def count_grid_ways(nums: List[int]) -> int:
    nums.sort()
    grid = [[], [], []]
    used = [False] * len(nums)
    return backtrack(nums, grid, used)

