def is_equilateral_triangle(a: int, b: int, c: int) -> bool:
    return (a + 2 == b and b + 2 == c) or (b + 2 == a and a + 2 == c) or (c + 2 == b and b + 2 == a)

def count_rotor_arrangements(n: int, masses: List[int]) -> int:
    if n != 9:
        raise ValueError("Only valid for n = 9")

    def dfs(index: int, groups: List[List[int]], used: List[bool], target_sum: int) -> int:
        if index == len(masses):
            return 1 if all(group and sum(group) == target_sum for group in groups) else 0

        count = 0
        for i in range(3):
            if not any(groups[i]):
                for j in [index + (i * 3)]:
                    if used[j]:
                        continue
                    used[j] = True
                    groups[i].append(masses[j])
                    count += dfs(index + 1, groups, used, target_sum)
                    groups[i].pop()
                    used[j] = False

        return count

    total_masses = sum(masses)
    if total_masses % 3 != 0:
        return 0
    target_sum = total_masses // 3

    result = 0
    for i in range(1, 8):
        for j in range(i + 1, 9):
            k = (i + j) % 9
            if is_equilateral_triangle(i, j, k):
                used = [False] * 9
                groups = [[], [], []]
                result += dfs(0, groups, used, target_sum)

    return result

