from scipy.optimize import minimize_scalar
import numpy as np

def g(x):
    return (x + 1) / (x - 2)

def distance_to_curve(mx, my):
    def dist_func(x):
        x_val = max(2.001, x)  # Ensure x > 2
        y_val = g(x_val)
        return np.sqrt((x_val - mx)**2 + (y_val - my)**2)

    result = minimize_scalar(dist_func)
    min_dist = result.fun
    return round(min_dist * 10, 2)

def solve_min_distance(mx: float, my: float) -> float:
    """
    Calculate the minimum distance between a point (mx, my) and the curve g(x) = (x + 1)/(x - 2) for x > 2,
    then multiply by 10 to convert to meters and round to two decimal places.

    :param mx: float - x-coordinate of the garden's boundary point
    :param my: float - y-coordinate of the garden's boundary point
    :return: float - minimum distance in meters, rounded to two decimal places
    """
    return distance_to_curve(mx, my)

