import itertools

def calculate_3430p(n: int) -> float:
    def is_valid(grid: List[List[int]]) -> bool:
        return all(sum(row) == 0 for row in grid)

    count = 0
    valid_count = 0

    for combination in itertools.product([-1, 0, 1], repeat=9):
        grid = [combination[i:i+3] for i in range(0, 9, 3)]
        if is_valid(grid):
            column_sums = [sum(col) for col in zip(*grid)]
            if all(s == 0 for s in column_sums):
                valid_count += 1
            count += 1

    p = valid_count / count if count != 0 else 0
    return round(n * p, 2)

