from typing import List

def quadratic_cost(n: int, cost_params: List[float]) -> float:
    a, b, c = cost_params
    return a * n + b * n ** 2 / 1000 + c

def maximize_profit_price(price: int, initial_customers: int, price_decrease_per_50_customers: int, new_customers_per_decrease: int, cost_params: List[float]) -> float:
    def profit(p):
        customers = initial_customers + (price - p) // (10000 // price_decrease_per_50_customers) * new_customers_per_decrease
        revenue = customers * p
        cost = quadratic_cost(customers, cost_params)
        return revenue - cost

    low, high = 0, price + 10000
    while high - low > 1:
        mid1 = low + (high - low) // 3
        mid2 = high - (high - low) // 3
        if profit(mid1) < profit(mid2):
            low = mid1
        else:
            high = mid2
    return round(max(profit(low), profit(high)), 2)

