def quadratic_cost(n: int) -> float:
    a = 0.01
    b = 28
    c = 15000
    return a * n**2 + b * n + c

def revenue(price: float, customers: int) -> float:
    return price * customers

def profit(price: float, customers: int) -> float:
    cost = quadratic_cost(customers)
    return (price - 200) * customers - cost

def maximize_profit_price(initial_price: float, initial_customers: int, decrease_step: float, new_customer_step: float, cost_params: list[float]) -> float:
    a, b, c = cost_params
    price = initial_price
    customers = initial_customers

    for i in range(int((initial_price - 200) / decrease_step)):
        current_profit = profit(price, customers)
        next_price = price - decrease_step
        next_customers = customers + new_customer_step * (decrease_step / 10000)

        if profit(next_price, next_customers) < current_profit:
            break
        else:
            price -= decrease_step

    return round(price, 2)

