def binom_coeff(n: int, k: int) -> int:
    if k > n:
        return 0
    if k == 0 or k == n:
        return 1
    k = min(k, n - k)
    coeff = 1
    for i in range(k):
        coeff *= (n - i + 1)
        coeff //= (i + 1)
    return coeff

def calculate_probability_score(questions: int, correct_points: int, incorrect_points: int, target_score: int) -> float:
    if questions * correct_points < target_score or (target_score - questions * correct_points) % (correct_points - incorrect_points) != 0:
        return 0.0

    num_correct = (target_score + questions * incorrect_points) // (correct_points - incorrect_points)

    if num_correct > questions:
        return 0.0

    prob = binom_coeff(questions, num_correct) * (1/4)**num_correct * (3/4)**(questions - num_correct)
    return round(prob * 100, 2)

