def distance(point1: Tuple[float, float, float], point2: Tuple[float, float, float]) -> float:
    return ((point1[0] - point2[0]) ** 2 + (point1[1] - point2[1]) ** 2 + (point1[2] - point2[2]) ** 2) ** 0.5

def solve_gps_problem(A: Tuple[float, float, float], B: Tuple[float, float, float], C: Tuple[float, float, float], D: Tuple[float, float, float]) -> float:
    def parametric_point_on_line(t: float, point1: Tuple[float, float, float], point2: Tuple[float, float, float]) -> Tuple[float, float, float]:
        return (point1[0] + t * (point2[0] - point1[0]), point1[1] + t * (point2[1] - point1[1]), point1[2] + t * (point2[2] - point1[2]))

    def distance_from_point_to_line(point: Tuple[float, float, float], line_start: Tuple[float, float, float], line_end: Tuple[float, float, float]) -> float:
        v1 = (line_end[0] - line_start[0], line_end[1] - line_start[1], line_end[2] - line_start[2])
        v2 = (point[0] - line_start[0], point[1] - line_start[1], point[2] - line_start[2])
        cross_product = (v1[1]*v2[2] - v1[2]*v2[1], v1[2]*v2[0] - v1[0]*v2[2], v1[0]*v2[1] - v1[1]*v2[0])
        line_length = distance(line_start, line_end)
        return (cross_product[0]**2 + cross_product[1]**2 + cross_product[2]**2) ** 0.5 / line_length

    max_sum_distance = 0
    best_point = None
    for t in range(1000):
        M = parametric_point_on_line(t / 999, A, B)
        sum_distance = (distance_from_point_to_line(A, D, M) + 
                        distance_from_point_to_line(B, D, M) + 
                        distance_from_point_to_line(C, D, M))
        if sum_distance > max_sum_distance:
            max_sum_distance = sum_distance
            best_point = M

    return round(sum(best_point), 2)

