def calculate_final_value(N: int) -> float:
    # Calculate the number of valid colorings for the octahedron
    def count_colorings():
        # There are 3 choices for the first face's color
        # For each subsequent face, there are 2 choices (different from adjacent faces)
        # Since it's a regular octahedron, we need to consider the symmetries
        return 3 * (2 ** 7) // 8

    # Calculate the number of valid numberings for the faces given the colors
    def count_numberings(colors):
        from itertools import permutations

        # Generate all possible numberings for a given color configuration
        def is_valid_parity(permutation):
            for i in range(4):
                if permutation[i] + permutation[(i+1) % 4] != 7:
                    return False
            return True

        valid_numberings = 0
        # Iterate over all permutations of numbers 1 to 4 for each color group
        for perm1 in permutations([1, 2, 3, 4]):
            for perm2 in permutations([1, 2, 3, 4]):
                for perm3 in permutations([1, 2, 3, 4]):
                    if is_valid_parity(perm1) and is_valid_parity(perm2) and is_valid_parity(perm3):
                        valid_numberings += 1

        # Each valid coloring can be arranged in (8! / (4! * 4!)) ways
        return factorial(8) // (factorial(4) ** 2) * valid_numberings

    colorings = count_colorings()
    numberings = count_numberings()

    N = colorings * numberings
    return N / 8 + 16

