    def is_valid_distribution(slots):
        count_1s = slots.count(1)
        count_2s = slots.count(2)
        if count_1s + 2 * count_2s != n_books or abs(count_1s - count_2s) not in [4, 6]:
            return False
        for i in range(len(slots)):
            if slots[i] == 2:
                if i > 0 and slots[i-1] in [1, 2]: return False
                if i < len(slots) - 1 and slots[i+1] in [1, 2]: return False
        return True

