    for count_1s in range(max(0, n_books - 6), min(n_books + 1, n_slots * 2)):
        count_2s = (n_books - count_1s) // 2
        if abs(count_1s - count_2s) not in [4, 6]:
            continue
        for slots_1 in comb(n_slots, count_1s):
            remaining_slots = n_slots - count_1s
            for slots_2 in comb(remaining_slots, count_2s):
                distribution = [0] * n_slots
                slot_idx = 0
                for _ in range(count_1s):
                    distribution[slot_idx] = 1
                    slot_idx += 1
                for _ in range(count_2s):
                    while True:
                        idx = slot_idx + 1
                        if idx < n_slots and (distribution[idx] == 0 or distribution[idx-1] != 2) and (idx+1 >= n_slots or distribution[idx+1] != 2):
