def find_min_first_payment(debt: float, target_percentage: float, months: int, decay_ratio: float) -> int:
    """
    Finds the minimum integer first-month payment to pay off a certain percentage of debt within a given number of months.

    :param debt: Total debt amount as a float
    :param target_percentage: Target percentage of debt to be paid off as a decimal (0-1)
    :param months: Number of months to pay off the debt
    :param decay_ratio: Ratio by which each month's payment decreases from the previous month
    :return: Minimum integer first-month payment
    """

    def calculate_payment(month: int, remaining_debt: float) -> float:
        if month == 1:
            return remaining_debt / (1 - target_percentage)
        else:
            next_month_payment = calculate_payment(month - 1, remaining_debt * decay_ratio)
            return max(0, next_month_payment * decay_ratio + remaining_debt * (target_percentage * decay_ratio))

    low, high = 1, int(debt / min(target_percentage, 1 - target_percentage)) + 1
    while low < high:
        mid = (low + high) // 2
        if sum(mid * decay_ratio ** i for i in range(months)) < debt * target_percentage:
            low = mid + 1
        else:
            high = mid

    return low

