def find_min_first_payment(debt: float, target_percentage: float, months: int, decay_ratio: float) -> Union[int, float]:
    if debt * target_percentage <= 0:
        return 0

    def simulate_payments(first_month_payment: float) -> float:
        remaining_debt = debt
        for month in range(months):
            payment = first_month_payment * (decay_ratio ** month)
            remaining_debt -= payment
            if remaining_debt <= 0:
                break
        return remaining_debt

    low, high = 1, debt / target_percentage
    while low < high:
        mid = (low + high) / 2
        remaining_debt = simulate_payments(mid)
        if remaining_debt > -target_percentage * debt:
            high = mid
        else:
            low = mid

    return round(low)

